<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useProfileStore } from '../../stores/profile'
const store=useProfileStore(); const step=ref(1); const saving=ref(false); const message=ref(''); const value=reactive<any>({province:null,exam_type:'普通',first_subject:null,second_subjects:[],score:null,rank:null,color_vision:null,vision_left:null,vision_right:null,tuition_budget:null,household_type:null,home_county:null,accept_adjustment:null})
onMounted(async()=>{await store.load();if(store.profile)Object.assign(value,store.profile)})
async function save(next=false){saving.value=true;message.value='';try{const p=await store.save({...value,second_subjects:value.second_subjects?.filter(Boolean)});Object.assign(value,p);message.value='档案已保存';if(next)step.value=2}catch(e:any){message.value=e.message||'保存失败'}finally{saving.value=false}}
</script>
<template><section class="content-page"><div class="eyebrow">PROFILE / {{step===1?'01':'02'}}</div><h1>考生档案</h1><p class="lede">档案是资格判断和方案排序的共同起点。可跳过体检信息，但相关专业会显示待核验风险。</p><div class="feature-card" v-if="store.completeness"><b>档案完成度 {{store.completeness.percent}}%</b><p v-if="store.completeness.missing?.length">待完善：{{store.completeness.missing.join('、')}}</p></div><div class="form-grid" v-if="step===1"><label>报考省份<input v-model="value.province" placeholder="河南"/></label><label>考试类型<select v-model="value.exam_type"><option>普通</option><option>艺术</option><option>体育</option></select></label><label>首选科目<select v-model="value.first_subject"><option :value="null">请选择</option><option>物理</option><option>历史</option></select></label><label>再选科目（逗号分隔）<input :value="value.second_subjects?.join(',')" @input="value.second_subjects=($event.target as HTMLInputElement).value.split(',').map(x=>x.trim()).filter(Boolean)"/></label><label>高考分数<input v-model.number="value.score" type="number" min="0" max="750"/></label><label>省内位次<input v-model.number="value.rank" type="number" min="1"/></label></div><div class="form-grid" v-else><label>色觉<select v-model="value.color_vision"><option :value="null">暂不填写</option><option>正常</option><option>色弱</option><option>色盲</option></select></label><label>左眼裸眼视力<input v-model.number="value.vision_left" type="number" step="0.1"/></label><label>右眼裸眼视力<input v-model.number="value.vision_right" type="number" step="0.1"/></label><label>年学费预算<input v-model.number="value.tuition_budget" type="number" min="0" placeholder="元/年，可跳过"/></label><label>户籍类型<select v-model="value.household_type"><option :value="null">暂不填写</option><option>农村</option><option>城镇</option></select></label><label>户籍所在县<input v-model="value.home_county" placeholder="可跳过"/></label><label>是否接受专业调剂<select v-model="value.accept_adjustment"><option :value="null">暂不填写</option><option :value="true">接受</option><option :value="false">不接受</option></select></label></div><p v-if="message" class="state-box">{{message}}</p><div class="hero-actions"><button v-if="step===2" class="text-btn" @click="step=1">返回基础信息</button><button class="primary" :disabled="saving" @click="save(step===1)">{{saving?'保存中…':step===1?'保存并继续':'保存档案 ↗'}}</button></div></section></template>
